result = {}
refs = {'MSFT': 'dataset_e248bd6c7b6b1e5698', 'NVDA': 'dataset_28795c781f261bb054'}
frames = {}
for t, r in refs.items():
    df = get_frame(r).copy()
    df['time'] = df['time'].astype(str)
    frames[t] = df.sort_values('time').reset_index(drop=True)

def seg(t, start, end):
    df = frames[t]
    s = df[(df['time'] >= start) & (df['time'] <= end)]
    if s.empty:
        return None
    return {'start': start, 'end': end, 'days': int(len(s)),
            'first_close': round(float(s['close'].iloc[0]), 2),
            'last_close': round(float(s['close'].iloc[-1]), 2),
            'min_close': round(float(s['close'].min()), 2),
            'return_pct': round((float(s['close'].iloc[-1]) / float(s['close'].iloc[0]) - 1) * 100, 2),
            'max_drawdown_pct': round((float(s['close'].min()) / float(s['close'].max()) - 1) * 100, 2)}

result['common_window_nov04_nov11'] = {t: seg(t, '2026-11-04', '2026-11-11') for t in refs}
result['election_window_nov05_nov06'] = {t: seg(t, '2026-11-04', '2026-11-06') for t in refs}

m = frames['MSFT'][['time', 'close']].rename(columns={'close': 'msft'})
n = frames['NVDA'][['time', 'close']].rename(columns={'close': 'nvda'})
mg = m.merge(n, on='time').sort_values('time')
sel = mg[(mg['time'] >= '2026-10-15')]
sel = sel.assign(msft_idx=sel['msft'] / sel['msft'].iloc[0] * 100, nvda_idx=sel['nvda'] / sel['nvda'].iloc[0] * 100)
result['oct15_onward_rows'] = [{'time': r['time'], 'msft_idx': round(r['msft_idx'], 2), 'nvda_idx': round(r['nvda_idx'], 2), 'msft_close': round(r['msft'], 2), 'nvda_close': round(r['nvda'], 2)} for _, r in sel.iterrows()]

